    features: [{"name":"Website Agent","description":"The largest surface. Routine-building and product questions on the storefront."},{"name":"Instagram AI","description":"Nearly a third of all chats. Where discovery actually happens for a brand that markets on Reels."},{"name":"WhatsApp AI","description":"Order status and the repeat-purchase relationship."},{"name":"AI Quiz and Discovery","description":"Guided routine matching for shoppers who describe a scalp or skin problem rather than name a product."},{"name":"Messenger AI","description":"The fourth surface, connected on the same shared memory so a Meta chat that starts on Instagram can continue in Messenger without the customer repeating herself."},{"name":"Segmentation","description":"Turns a described concern (hair fall, dandruff, acne) into a live audience attribute rather than a static list."}],
