    ogImage: "/casestudy/sylvi-watches-og.jpg",
    answer: "Sylvi Watches, a Surat-based Indian watch brand on Shopify, runs YourLio AI across its Website Agent, WhatsApp AI, Instagram AI and Messenger AI on one shared customer memory. Between 1 July and 7 September 2026 the agent handled over 6,000 chats, resolved 84.37% without a human, and carried 291 repair and warranty enquiries alongside pre-sale discovery.",
    stats: [{"value":"4","display":"4","label":"channels on one shared customer memory"},{"value":"291","display":"291","label":"repair and warranty journeys automated end to end"},{"value":"17.1%","display":"17%","label":"of store sales ran through a YourLio chat, August 2026"}],
    features: [{"name":"Website Agent","description":"The main discovery surface, budget filters, spec questions, collection browsing."},{"name":"WhatsApp AI","description":"Order status, warranty registration and the repair chat."},{"name":"Instagram AI","description":"Social discovery from a heavily visual, creative-led feed."},{"name":"Messenger AI","description":"The fourth surface, small but on the same customer memory."},{"name":"Nudge Engine","description":"Prompts across a very large browsing audience with a low question rate."}],
