    features: [{"name":"WhatsApp AI","description":"The primary channel, carrying 73.8% of chats. Bookings, confirmations and follow-up live in one persistent thread."},{"name":"Website Agent","description":"Frame discovery and lens explanation on the storefront."},{"name":"Instagram AI","description":"Social discovery from frame-led creative."},{"name":"AI Popups","description":"Offer-led entry on a catalog where discount questions are a top-three intent."}],
