    dataTable: {"title":"Chat intent mix, 24 Jul to 7 Sep 2026","headers":["Intent","Chats","Type"],"rows":[["Product Info","443","Application and suitability"],["Product Discovery","178","Curl-type matching"],["Product Browsing","146","Catalog navigation"],["Guided quiz","99","Structured discovery"],["Checkout Enquiry","40","Pre-sale"],["Order Tracking","15","Post-purchase"],["Offer / Rewards","15","Pre-sale"]]},
