/* Display order for every study, consented or not, so the two files merge back
   into one list in the right order. */
export const ORDER = ["north-sole","soulflower","dr-ortho","bluetea","lets-tilt","deodap","sylvi-watches","auravedic","rippedup-nutrition","yourspex","cureayu","ashba-botanics","blue-nectar","bake-cosmetics","ugees","nysh"];

/* Studies still awaiting consent live in a gitignored sibling that only exists
   on a machine where someone has generated it. import.meta.glob rather than a
   static import: a missing file is an empty result instead of a build error,
   and import.meta.env.DEV is replaced at build time so the whole branch is
   dropped from a production bundle. */
// Only consented studies ship on this site.
const PENDING = [];

const rank = (cs) => {
  const i = ORDER.indexOf(cs.slug);
  return i === -1 ? ORDER.length : i;
};

/* Everything downstream (routes, index, sitemap, JSON-LD) reads these, never
   CASE_STUDIES directly. In production this is exactly the consented list; in
   dev the held studies are merged in so they can be reviewed. */
export function getAllCaseStudies() {
  return [...CASE_STUDIES, ...PENDING].sort((a, b) => rank(a) - rank(b));
}

export function getCaseStudyBySlug(slug) {
  return getAllCaseStudies().find((cs) => cs.slug === slug);
}

/* Up to limit other studies, preferring a different use case so the related
   rail widens the reader's view instead of repeating it. */
export function getRelatedCaseStudies(slug, limit = 3) {
  const all = getAllCaseStudies();
  const current = all.find((cs) => cs.slug === slug);
  const rest = all.filter((cs) => cs.slug !== slug);
  const other = rest.filter((cs) => cs.useCase !== current?.useCase);
  const same = rest.filter((cs) => cs.useCase === current?.useCase);
  return [...other, ...same].slice(0, limit);
}
